#include <utility>
#include <vector>

class ResourceHandle {
private:
    std::vector<int> data; // Large resource
public:
    void swap(ResourceHandle& other) noexcept {
        // O(1) swap of internal vector states
        using std::swap;
        swap(data, other.data);
    }
};

// Non-member swap for ADL
void swap(ResourceHandle& a, ResourceHandle& b) noexcept {
    a.swap(b);
}

